QuenchOilDipperMaker.productStock = {}; QuenchOilDipperMaker.buildings = {}; QuenchOilDipperMaker.maker = nil; QuenchOilDipperMaker.activeMaking = {}; QuenchOilDipperMaker.totalProducts = 0; QuenchOilDipperMaker.dayTimer = 0
function QuenchOilDipperMaker.init() QuenchOilDipperMaker.ironStock=14; QuenchOilDipperMaker.bronzeStock=12; QuenchOilDipperMaker.woodStock=14; QuenchOilDipperMaker.leatherStock=8; QuenchOilDipperMaker.silverStock=8; QuenchOilDipperMaker.goldStock=6; QuenchOilDipperMaker.jewelStock=4; QuenchOilDipperMaker.pearlStock=4; QuenchOilDipperMaker.productStock={}; QuenchOilDipperMaker.buildings={}; QuenchOilDipperMaker.maker=nil; QuenchOilDipperMaker.activeMaking={}; QuenchOilDipperMaker.totalProducts=0; QuenchOilDipperMaker.dayTimer=0; print("[QuenchOilDipperMaker] Royal Quench Oil Dipper Maker System initialized (6 products, 4 buildings)") end
function QuenchOilDipperMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; QuenchOilDipperMaker.maker={name=n or ("Zajemalkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zajemalkar najet: %s (spretnost: %d)",QuenchOilDipperMaker.maker.name,s),"success") end; return true end
function QuenchOilDipperMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function QuenchOilDipperMaker.build(id) local ok,e=QuenchOilDipperMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(QuenchOilDipperMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function QuenchOilDipperMaker.getQualityBonus() local b=0; for _,bd in ipairs(QuenchOilDipperMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function QuenchOilDipperMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and QuenchOilDipperMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and QuenchOilDipperMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and QuenchOilDipperMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and QuenchOilDipperMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and QuenchOilDipperMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and QuenchOilDipperMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and QuenchOilDipperMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and QuenchOilDipperMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #QuenchOilDipperMaker.buildings==0 then return false,"Potrebna zajemalna delavnica" end; if not QuenchOilDipperMaker.maker then return false,"Potreben zajemalkar" end; return true end
function QuenchOilDipperMaker.make(pt,qty) qty=qty or 1; local ok,e=QuenchOilDipperMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then QuenchOilDipperMaker.ironStock=QuenchOilDipperMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then QuenchOilDipperMaker.bronzeStock=QuenchOilDipperMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then QuenchOilDipperMaker.woodStock=QuenchOilDipperMaker.woodStock-d.woodCost*qty end; if d.leatherCost then QuenchOilDipperMaker.leatherStock=QuenchOilDipperMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then QuenchOilDipperMaker.silverStock=QuenchOilDipperMaker.silverStock-d.silverCost*qty end; if d.goldCost then QuenchOilDipperMaker.goldStock=QuenchOilDipperMaker.goldStock-d.goldCost*qty end; if d.jewelCost then QuenchOilDipperMaker.jewelStock=QuenchOilDipperMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then QuenchOilDipperMaker.pearlStock=QuenchOilDipperMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if QuenchOilDipperMaker.maker then t=math.max(1,t-math.floor(QuenchOilDipperMaker.maker.skill/13)) end; table.insert(QuenchOilDipperMaker.activeMaking,{id="quencoildipper_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function QuenchOilDipperMaker.completeMaking(m) local q=1.0+(QuenchOilDipperMaker.getQualityBonus()/100); if QuenchOilDipperMaker.maker then q=q+(QuenchOilDipperMaker.maker.skill/140) end; q=math.min(2.5,q); QuenchOilDipperMaker.productStock[m.productType]=(QuenchOilDipperMaker.productStock[m.productType] or 0)+m.quantity; QuenchOilDipperMaker.totalProducts=QuenchOilDipperMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if QuenchOilDipperMaker.maker then QuenchOilDipperMaker.maker.itemsMade=QuenchOilDipperMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then QuenchOilDipperMaker.maker.skill=math.min(100,QuenchOilDipperMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zajemalka izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"quencoildipper.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function QuenchOilDipperMaker.update(dt) if not _G.state then return end; QuenchOilDipperMaker.dayTimer=QuenchOilDipperMaker.dayTimer+dt; if QuenchOilDipperMaker.dayTimer>=30 then QuenchOilDipperMaker.dayTimer=0; for i=#QuenchOilDipperMaker.activeMaking,1,-1 do local m=QuenchOilDipperMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then QuenchOilDipperMaker.completeMaking(m); table.remove(QuenchOilDipperMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(QuenchOilDipperMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if QuenchOilDipperMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function QuenchOilDipperMaker.getStats() return {ironStock=QuenchOilDipperMaker.ironStock,bronzeStock=QuenchOilDipperMaker.bronzeStock,woodStock=QuenchOilDipperMaker.woodStock,leatherStock=QuenchOilDipperMaker.leatherStock,silverStock=QuenchOilDipperMaker.silverStock,goldStock=QuenchOilDipperMaker.goldStock,jewelStock=QuenchOilDipperMaker.jewelStock,pearlStock=QuenchOilDipperMaker.pearlStock,productStock=QuenchOilDipperMaker.productStock,numBuildings=#QuenchOilDipperMaker.buildings,hasMaker=QuenchOilDipperMaker.maker~=nil,makerName=QuenchOilDipperMaker.maker and QuenchOilDipperMaker.maker.name or "—",makerSkill=QuenchOilDipperMaker.maker and QuenchOilDipperMaker.maker.skill or 0,activeMaking=#QuenchOilDipperMaker.activeMaking,totalProducts=QuenchOilDipperMaker.totalProducts} end
